19. package co.elastic.apm.agent.kafka.helper;
20. 
21. import co.elastic.apm.agent.configuration.MessagingConfiguration;
22. import co.elastic.apm.agent.impl.ElasticApmTracer;
23. import co.elastic.apm.agent.impl.GlobalTracer;
24. import co.elastic.apm.agent.impl.transaction.Span;
25. import co.elastic.apm.agent.matcher.WildcardMatcher;
26. import co.elastic.apm.agent.objectpool.Allocator;
27. import co.elastic.apm.agent.objectpool.ObjectPool;
28. import co.elastic.apm.agent.objectpool.impl.QueueBasedObjectPool;
29. import co.elastic.apm.agent.sdk.logging.Logger;
30. import co.elastic.apm.agent.sdk.logging.LoggerFactory;
31. import org.apache.kafka.clients.producer.Callback;
32. import org.apache.kafka.clients.producer.KafkaProducer;
33. import org.apache.kafka.clients.producer.ProducerRecord;
34. import org.apache.kafka.common.Node;
35. import org.apache.kafka.common.PartitionInfo;
36. import org.jctools.queues.atomic.AtomicQueueFactory;
37. 
38. import javax.annotation.Nullable;
39. import java.util.List;
40. 
41. import static org.jctools.queues.spec.ConcurrentQueueSpec.createBoundedMpmc;
42. 
43. public class KafkaInstrumentationHelper {
44. 
45.     public static final Logger logger = LoggerFactory.getLogger(KafkaInstrumentationHelper.class);
46.     private static final KafkaInstrumentationHelper INSTANCE = new KafkaInstrumentationHelper(GlobalTracer.requireTracerImpl());
47. 
48.     private final ObjectPool<CallbackWrapper> callbackWrapperObjectPool;
49.     private final ElasticApmTracer tracer;
50.     private final MessagingConfiguration messagingConfiguration;
51. 
52.     public static KafkaInstrumentationHelper get() {
53.         return INSTANCE;
54.     }
55. 
56.     public KafkaInstrumentationHelper(ElasticApmTracer tracer) {
57.         this.tracer = tracer;
58.         messagingConfiguration = tracer.getConfig(MessagingConfiguration.class);
59.         this.callbackWrapperObjectPool = QueueBasedObjectPool.ofRecyclable(
60.             AtomicQueueFactory.<CallbackWrapper>newQueue(createBoundedMpmc(256)),
61.             false,
62.             new CallbackWrapperAllocator()
63.         );
64.     }
65. 
66.     private final class CallbackWrapperAllocator implements Allocator<CallbackWrapper> {
67.         @Override
68.         public CallbackWrapper createInstance() {
69.             return new CallbackWrapper(KafkaInstrumentationHelper.this);
70.         }
71.     }
72. 
73.     private boolean ignoreTopic(String topicName) {
74.         return WildcardMatcher.isAnyMatch(messagingConfiguration.getIgnoreMessageQueues(), topicName);
75.     }
76. 
77.     @Nullable
78.     public Span onSendStart(ProducerRecord<?, ?> record) {
79. 
80.         String topic = record.topic();
81.         if (ignoreTopic(topic)) {
82.             return null;
83.         }
84. 
85.         final Span span = tracer.createExitChildSpan();
86.         if (span == null) {
87.             return null;
88.         }
89. 
90.         span.withType("messaging")
91.             .withSubtype("kafka")
92.             .withAction("send")
93.             .withName("KafkaProducer#send to ").appendToName(topic);
94. 
95.         span.getContext().getMessage()
96.             .withQueue(topic);
97. 
98.         span.getContext().getServiceTarget()
99.             .withType("kafka")
100.             .withName(topic);
101. 
102.         span.activate();
103.         return span;
104.     }
105. 
106.     @Nullable
107.     public Callback wrapCallback(@Nullable Callback callback, Span span) {
108.         if (callback instanceof CallbackWrapper) {
109.             // don't wrap twice
110.             return callback;
111.         }
112.         try {
113.             return callbackWrapperObjectPool.createInstance().wrap(callback, span);
114.         } catch (Throwable throwable) {
115.             logger.debug("Failed to wrap Kafka send callback", throwable);
116.             return callback;
117.         }
118.     }
119. 
120.     void recycle(CallbackWrapper callbackWrapper) {
121.         callbackWrapperObjectPool.recycle(callbackWrapper);
122.     }
123. 
124.     public void onSendEnd(Span span, ProducerRecord<?, ?> producerRecord, KafkaProducer<?, ?> kafkaProducer, @Nullable Throwable throwable) {
125. 
126.         // Topic address collection is normally very fast, as it uses cached cluster state information. However,
127.         // when the cluster metadata is required to be updated, its query may block for a short period. In
128.         // addition, the discovery operation allocates two objects. Therefore, we have the ability to turn it off.
129.         if (messagingConfiguration.shouldCollectQueueAddress()) {
130.             try {
131.                 // Better get the destination now, as if the partition's leader was replaced, it may be reflected at
132.                 // this point.
133.                 List<PartitionInfo> partitions = kafkaProducer.partitionsFor(producerRecord.topic());
134.                 Integer partition = producerRecord.partition();
135.                 PartitionInfo partitionInfo = null;
136.                 if (partition != null) {
137.                     partitionInfo = partitions.get(partition);
138.                 } else if (!partitions.isEmpty()) {
139.                     // probably not a partitioned topic, so look for the singe entry
140.                     partitionInfo = partitions.get(0);
141.                 }
142.                 if (partitionInfo != null) {
143.                     // Records are always sent to the leader of a partition and then synced with replicas internally by
144.                     // the broker.
145.                     Node leader = partitionInfo.leader();
146.                     if (leader != null) {
147.                         span.getContext().getDestination().withAddress(leader.host()).withPort(leader.port());
148.                     }
149.                 }
150.             } catch (Exception e) {
151.                 logger.error("Failed to get Kafka producer's destination", e);
152.             }
153.         }
154. 
155.         span.captureException(throwable);
156. 
157.         // Not ending here- ending in the callback
158.         span.deactivate();
159.     }
160. }
