102.         public boolean equals(Object o) {
103.             if (this == o) return true;
104.             if (o == null || getClass() != o.getClass()) return false;
105. 
106.             StatsKey statsKey = (StatsKey) o;
107. 
108.             if (serviceType != null ? !serviceType.equals(statsKey.serviceType) : statsKey.serviceType != null)
109.                 return false;
110.             if (!CharSequenceUtils.equals(serviceName, statsKey.serviceName)) return false;
111.             if (!CharSequenceUtils.equals(destinationResource, statsKey.destinationResource)) return false;
112.             return outcome == statsKey.outcome;
113.         }
