158.         @Override
159.         public Stats createInstance() {
160.             return new Stats();
161.         }
162.     });
163. 
164.     private final ConcurrentMap<StatsKey, Stats> statsMap = new ConcurrentHashMap<>();
165. 
166.     // only used during testing
167.     @Nullable
168.     Stats getStats(String serviceType, @Nullable String serviceName, Outcome outcome){
169.         ServiceTarget st = new ServiceTarget().withType(serviceType).withName(serviceName);
170.         return statsMap.get(new StatsKey().init(st, outcome));
171.     }
