173.     public void captureDroppedSpan(Span span) {
174.         ServiceTarget serviceTarget = span.getContext().getServiceTarget();
175.         if (!span.isExit() || !serviceTarget.hasContent() ) {
176.             return;
177.         }
178. 
179.         Stats stats = getOrCreateStats(serviceTarget, span.getOutcome());
180. 
181.         if (span.isComposite()) {
182.             stats.count.addAndGet(span.getComposite().getCount());
183.         } else {
184.             stats.count.incrementAndGet();
185.         }
186.         stats.sum.addAndGet(span.getDuration());
187.     }
