189.     private Stats getOrCreateStats(ServiceTarget serviceTarget, Outcome outcome) {
190.         StatsKey statsKey = statsKeyObjectPool.createInstance().init(serviceTarget, outcome);
191.         Stats stats = statsMap.get(statsKey);
192.         if (stats != null || statsMap.size() > 127) {
193.             statsKeyObjectPool.recycle(statsKey);
194.             return stats;
195.         }
196. 
197.         stats = statsObjectPool.createInstance();
198. 
199.         Stats oldStats = statsMap.putIfAbsent(statsKey, stats);
200.         if (oldStats != null) {
201.             statsKeyObjectPool.recycle(statsKey);
202.             statsObjectPool.recycle(stats);
203.             return oldStats;
204.         }
205. 
206.         return stats;
